const slides=[];const S=(chapter,kicker,title,html)=>slides.push({chapter,kicker,title,html});
const panel=(html,accent='blue')=>`<div class="panel ${accent}">${html}</div>`;
const question=(title,prompt)=>`<div class="discuss"><h3>${title}</h3><p>${prompt}</p></div>`;
const reveal=(id,label,html)=>`<button class="btn alt reveal" data-target="${id}" aria-expanded="false">${label}</button><div class="answer" id="${id}">${html}</div>`;
const notebook=(html)=>`<div class="panel emphasis"><span class="tag">✍️ Copia en el cuaderno</span>${html}</div>`;
const book=(page,nums,tip='Hazlo en el cuaderno. Después podemos comentar el razonamiento en clase.')=>`<div class="panel blue"><span class="tag">📘 Actividad del libro</span><h2>Página ${page} · ${nums}</h2><p>${tip}</p><div class="big-space"></div></div>`;
const statePhoto=(position,alt,caption,showNote=true)=>`<figure class="state-photo-figure"><div class="state-photo" role="img" aria-label="${alt}" style="background-image:url('assets/estados-fotorrealistas.webp');background-position:${position}"></div><figcaption>${caption}${showNote?'<span>Recreación fotorealista</span>':''}</figcaption></figure>`;
const properties=(items)=>`<ul class="state-properties">${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const stateDiagram=(mode)=>`<div class="panel particle-box center"><div class="particles ${mode}">${Array.from({length:mode==='gas'?13:25},()=>'<i></i>').join('')}</div><p class="small">Representación simplificada de partículas</p></div>`;

const curvePlot=(series,{min=-20,max=120,tmax=16,ticks=[0,40,100],xticks=[0,4,8,12,16],labels=[]}={})=>{
 const x=t=>85+t/tmax*640,y=T=>365-(T-min)/(max-min)*300;
 return `<svg class="lesson-chart" viewBox="0 0 810 445" role="img" aria-label="Gráfica de temperatura en grados Celsius frente al tiempo en minutos"><g font-family="Arial" font-size="24" fill="currentColor">${ticks.map(T=>`<path d="M85 ${y(T)}H725" stroke="currentColor" opacity=".17" stroke-dasharray="5 7"/><text x="70" y="${y(T)+8}" text-anchor="end">${T}</text>`).join('')}${xticks.map(t=>`<text x="${x(t)}" y="398" text-anchor="middle">${t}</text>`).join('')}<path d="M85 50V365H740" fill="none" stroke="currentColor" stroke-width="3"/><text x="18" y="32">T (°C)</text><text x="535" y="434">Tiempo (min)</text>${series.map(a=>`<polyline points="${a.points.map(([t,T])=>x(t)+','+y(T)).join(' ')}" fill="none" stroke="${a.color||'#ffc472'}" stroke-width="6" stroke-linejoin="round"/>${a.points.map(([t,T])=>`<circle cx="${x(t)}" cy="${y(T)}" r="5" fill="${a.color||'#ffc472'}"/>`).join('')}`).join('')}${labels.map(([t,T,label])=>`<text x="${x(t)}" y="${y(T)-16}" text-anchor="middle" font-weight="bold">${label}</text>`).join('')}</g></svg>`;
};
const chalk=(graph,body)=>`<div class="chalk-lesson"><div class="chalk-chart">${graph}</div><div class="chalk-notes">${body}</div></div>`;

