S('estados','Conocer los estados de agregación','¿De qué depende el estado?',`<div class="conditions-definition"><p>El estado de agregación depende de la <strong>temperatura</strong> y de la <strong>presión</strong>.</p><span class="tag">✍️ Copia en el cuaderno</span></div><div class="condition-comparisons"><section class="condition-card temperature-card"><h3><span class="condition-number">01</span> Cambia la temperatura</h3><div class="comparison-context">La misma sustancia: <strong>agua</strong></div><figure class="landscape-comparison"><img src="assets/paisaje-temperaturas.webp" alt="El mismo lago: a la izquierda agua líquida en un paisaje templado; a la derecha agua congelada en invierno"></figure><div class="condition-pair-labels"><div><strong>Más temperatura</strong><span>Agua líquida</span></div><div><strong>Menos temperatura</strong><span>Hielo · sólido</span></div></div><p class="condition-explanation">La temperatura puede cambiar su estado.</p></section><section class="condition-card pressure-card"><h3><span class="condition-number">02</span> Cambia la presión</h3><div class="comparison-context">La misma sustancia: <strong>butano</strong> · temperatura ambiente</div><div class="butane-comparison">${butaneDiagram}</div><div class="condition-pair-labels"><div><strong>Dentro de la bombona</strong><span>Mayor presión · líquido y vapor</span></div><div><strong>A presión atmosférica</strong><span>Menor presión · gas</span></div></div><p class="condition-explanation">La presión permite almacenar butano líquido.</p></section></div><div class="conditions-prompt"><strong>Observa y explica:</strong> ¿qué condición cambia en cada ejemplo?</div>`);

const closedAirSyringe=(compressed)=>{const x=compressed?185:77;const points=Array.from({length:16},(_,i)=>({x:x+18+(i%4)*(305-x-18)/3,y:68+Math.floor(i/4)*19}));return `<svg viewBox="0 0 390 190" role="img" aria-label="${compressed?'Mayor':'Menor'} presión: el mismo aire en una jeringuilla cerrada, a temperatura constante"><defs><linearGradient id="barrel-${x}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d0eaf6"/><stop offset=".45" stop-color="#fff"/><stop offset="1" stop-color="#c9e4f1"/></linearGradient><linearGradient id="orange-${x}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ffbb7c"/><stop offset=".5" stop-color="#e47c3c"/><stop offset="1" stop-color="#bc5725"/></linearGradient></defs><ellipse cx="200" cy="153" rx="165" ry="10" fill="#d9e7ef"/><rect x="57" y="42" width="270" height="101" rx="14" fill="url(#barrel-${x})" stroke="#5b8fac" stroke-width="3"/><path d="M327 69H360V116H327Z" fill="#dfedf5" stroke="#5b8fac" stroke-width="3"/><path d="M360 67V119" stroke="#e47c3c" stroke-width="8" stroke-linecap="round"/><rect x="${x+6}" y="50" width="${315-x}" height="85" rx="7" fill="#d5edfa" opacity=".7"/><path d="M18 92H${x-5}" stroke="url(#orange-${x})" stroke-width="13" stroke-linecap="round"/><path d="M18 64V120" stroke="url(#orange-${x})" stroke-width="13" stroke-linecap="round"/><rect x="${x-4}" y="47" width="14" height="91" rx="5" fill="#2c5670"/><path d="M68 36V150" stroke="#5b8fac" stroke-width="5" stroke-linecap="round"/>${points.map(v=>`<circle cx="${v.x}" cy="${v.y}" r="5" fill="#358dbb" stroke="#216c92" stroke-width="1"/>`).join('')}<path d="M90 47H314" stroke="#fff" stroke-width="4" opacity=".8"/></svg>`};

const characteristicsTree=`<figure class="notebook-sketchnote"><img src="assets/diapo6-sketchnote.webp" alt="Estados de agregación. Forma y capacidad de fluir: los sólidos tienen forma propia; los líquidos y gases adoptan la forma del recipiente y fluyen. Volumen propio: sólidos y líquidos tienen volumen propio; los gases ocupan todo el volumen disponible. Compresibilidad: capacidad de reducir el volumen al aplicar presión; en sólidos es inapreciable, en líquidos muy baja y los gases son fácilmente compresibles. Ejemplos: hielo, agua en recipientes y aire en un cilindro cerrado con émbolo."></figure>`;

