S('estados','Conocer los estados de agregación','El estado líquido',`<div class="two"><div class="panel green">${properties(['<strong>No tienen forma propia</strong>, pero sí <strong>volumen propio</strong>.','Pueden <strong>fluir</strong>.','Tienen <strong>baja compresibilidad</strong>.','Se pueden <strong>dilatar térmicamente</strong>.'])}</div>${statePhoto('right top','Un vaso transparente que contiene agua líquida','Ejemplo: agua líquida en un vaso.',false)}</div>`);
S('estados','Conocer los estados de agregación','El estado gaseoso',`<div class="two"><div class="panel yellow">${properties(['No tienen <strong>forma ni volumen propios</strong>.','Son <strong>fluidos</strong>.','Son <strong>fácilmente compresibles</strong>.','Se pueden <strong>expandir térmicamente</strong>.'])}</div>${statePhoto('left bottom','Globo azul inflado que contiene aire','Ejemplo: el aire dentro del globo. El gas es invisible.',false)}</div>`);
S('estados','Conocer los estados de agregación','El plasma',`<div class="two"><div class="panel emphasis"><span class="tag">El cuarto estado</span><p class="large">El <strong>plasma</strong> es un estado de la materia formado por partículas cargadas.</p><p class="large">Lo encontramos en las estrellas, como el <strong>Sol</strong>.</p><p class="small">Incluye el plasma entre los estados que debes conocer.</p></div>${statePhoto('right bottom','Recreación del Sol completo sobre un fondo negro','Ejemplo: el Sol, cuya materia está en estado de plasma.')}</div>`);

