S('cambios','3 · Cambios de estado','¿Qué ocurre al calentar?',`<div class="panel blue center phase-intro"><p class="intro-sentence">Un cubito de hielo se funde, y si seguimos calentando el agua, pasa a gas.</p><div class="phase-oral"><span>🧊<br><strong>SÓLIDO</strong></span><b>→</b><span>💧<br><strong>LÍQUIDO</strong></span><b>→</b><span>◌<br><strong>GAS</strong></span></div></div>${question('Lo comentamos juntos','¿Cómo se llama cada paso? ¿Y el paso directo de sólido a gas, sin pasar por líquido?')}${reveal('oralHeating','Mostrar respuesta','<p class="large">Sólido → líquido: <strong>fusión</strong>.<br>Líquido → gas: <strong>vaporización</strong>.<br>Sólido → gas: <strong>sublimación</strong>.</p>')}`);
S('cambios','','¿Qué ocurre al enfriar?',`<div class="panel blue center phase-intro"><p class="intro-sentence">El vapor de agua se enfría, puede pasar a líquido y, si seguimos enfriando, a hielo.</p><div class="phase-oral"><span>◌<br><strong>GAS</strong></span><b>→</b><span>💧<br><strong>LÍQUIDO</strong></span><b>→</b><span>🧊<br><strong>SÓLIDO</strong></span></div></div>${question('Lo comentamos juntos','¿Cómo se llama cada paso? ¿Y el paso directo de gas a sólido, sin pasar por líquido?')}${reveal('oralCooling','Mostrar los nombres','<p class="large">Gas → líquido: <strong>condensación</strong>.<br>Líquido → sólido: <strong>solidificación</strong>.<br>Gas → sólido: <strong>sublimación inversa</strong>.</p>')}`);

S('cambios','Seis nombres','El mapa de los cambios',`<figure class="notebook-sketchnote phase-poster"><img src="assets/cambios-estado-pizarra-v2.webp" width="1920" height="1080" decoding="async" fetchpriority="high" alt="Cambios de estado. Sólido a líquido: fusión. Líquido a sólido: solidificación. Líquido a gas: vaporización. Gas a líquido: condensación. Sólido a gas: sublimación. Gas a sólido: sublimación inversa."></figure>`);
S('cambios','¿Te lo sabes?','De sólido a gas',`<div class="phase-activity"><div class="phase-sequence"><strong>Sólido</strong><b>→</b><span class="blank phase-blank" data-answer="Fusión" tabindex="0" role="button" aria-label="Revelar el paso de sólido a líquido"><span aria-hidden="true">?</span></span><b>→</b><strong>Líquido</strong><b>→</b><span class="blank phase-blank" data-answer="Vaporización" tabindex="0" role="button" aria-label="Revelar el paso de líquido a gas"><span aria-hidden="true">?</span></span><b>→</b><strong>Gas</strong></div><p class="phase-instruction">Decid el nombre en voz alta y pulsad cada rectángulo.</p><h3>¿Cómo se llama el paso directo de sólido a gas?</h3>${reveal('direct','Mostrar respuesta','<div class="phase-reply"><div><h3>Sublimación</h3><p>El sólido pasa directamente a gas, <strong>sin pasar por líquido</strong>.</p><p><strong>Ejemplo: hielo seco.</strong> El CO₂ sólido pasa a CO₂ gaseoso.</p></div><div class="phase-example"><p class="large">Hielo seco → CO₂ gas</p><a class="btn" href="https://youtube.com/shorts/VXxxrh9oMxA?si=KL5E0F_xlk-bbB6A" target="_blank" rel="noopener">▶ Ver el vídeo</a></div></div>')}</div>`);
S('cambios','Decimos y comprobamos','El recorrido inverso',`<div class="phase-activity"><div class="phase-sequence"><strong>Gas</strong><b>→</b><span class="blank phase-blank" data-answer="Condensación" tabindex="0" role="button" aria-label="Revelar el paso de gas a líquido"><span aria-hidden="true">?</span></span><b>→</b><strong>Líquido</strong><b>→</b><span class="blank phase-blank" data-answer="Solidificación" tabindex="0" role="button" aria-label="Revelar el paso de líquido a sólido"><span aria-hidden="true">?</span></span><b>→</b><strong>Sólido</strong></div><p class="phase-instruction">Decid el nombre en voz alta y pulsad cada rectángulo.</p><h3>¿Cómo se llama el paso directo de gas a sólido?</h3>${reveal('inverse','Mostrar respuesta','<div class="phase-reply"><div><h3>Sublimación inversa</h3><p>El gas pasa directamente a sólido, <strong>sin pasar por líquido</strong>.</p><p><strong>Ejemplo: escarcha.</strong> El vapor de agua del aire pasa directamente a cristales de hielo sobre una superficie muy fría.</p><p class="phase-tip">Vapor de agua → hielo</p></div><figure class="phase-crystals"><img src="https://www.noaa.gov/sites/default/files/styles/default_width_856/public/2024-01/IceCrystal4AndThreeQuarterInchesInDiameter_28Feb1936_CC.jpg?h=ebfcafff&itok=TjOR7QWC" alt="Fotografía real de un cristal de hielo con ramificaciones" referrerpolicy="no-referrer"><figcaption>Cristales de hielo</figcaption></figure></div>')}</div>`);
S('cambios','Propiedades específicas','Cada sustancia tiene su propia temperatura de cambio de estado',`<div class="specific-temperatures"><ul class="specific-bullets"><li>Los <strong>puntos de fusión y ebullición</strong> son <strong>propiedades específicas o características</strong>: ayudan a identificar las sustancias.</li><li>Una <strong>sustancia pura, a una presión determinada</strong>, cambia de estado a temperaturas propias. No dependen de la cantidad de sustancia.</li></ul><h3>Ejemplo: ¿qué ocurre con el agua a estas temperaturas?</h3><table class="water-state-table"><tr><th>Temperatura</th><th>−5 °C</th><th>0 °C</th><th>20 °C</th><th>100 °C</th><th>110 °C</th></tr><tr><th>Estado / cambio</th>${['🧊<br><strong>Sólido</strong>','🧊 + 💧<br><strong>Fusión / solidificación</strong>','💧<br><strong>Líquido</strong>','💧 + ◌<br><strong>Ebullición / condensación</strong>','◌<br><strong>Gas</strong>'].map((answer,i)=>`<td><button class="water-state-cell" data-water-answer="${i}" aria-label="Mostrar el estado a ${[-5,0,20,100,110][i]} grados Celsius" aria-expanded="false">?</button></td>`).join('')}</tr></table><p class="small">Agua a presión atmosférica. Pulsa cada casilla después de responder.</p></div>`);

S('cambios','Ejercicios de gráficas','Ejemplo de calentamiento',`<div class="two"><div class="diagram">${graph()}</div>${panel('<ul class="graph-reading"><li>Lee <strong>de izquierda a derecha</strong>.</li><li>Los <strong>tramos inclinados</strong> indican que la temperatura <strong>aumenta</strong>.</li><li>Los <strong>tramos horizontales</strong> corresponden a cambios de estado.</li></ul><p><strong>Durante el cambio de estado, la temperatura permanece constante.</strong></p>','blue')}</div><div class="graph-question"><p>¿Qué dos cambios de estado corresponden a las mesetas si partimos de un sólido? Localízalas.<br>¿Qué cambia en la materia aunque la temperatura no suba?</p>${reveal('heatans','Mostrar respuesta','<p><strong>Primera meseta:</strong> fusión (sólido y líquido).<br><strong>Segunda meseta:</strong> ebullición (líquido y gas).<br>La materia <strong>cambia de estado</strong>; la energía aportada permite cambiar la organización y separación de las partículas, sin aumentar la temperatura durante el cambio.</p>')}</div>`);
S('cambios','Ejercicios de gráficas','Ejemplo de enfriamiento',`<div class="two"><div class="diagram">${graph(true)}</div>${panel('<ul class="graph-reading"><li>En este caso <strong>cedemos calor</strong>.</li><li>Los <strong>tramos inclinados</strong> indican que la temperatura <strong>disminuye</strong>.</li><li>En los <strong>tramos horizontales</strong> ocurren cambios de estado.</li></ul><p><strong>Durante el cambio de estado, la temperatura permanece constante.</strong></p>','blue')}</div><div class="graph-question"><p>¿Qué dos cambios de estado podrían corresponder a las mesetas si partimos de un gas?</p>${reveal('coolans','Mostrar respuesta','<p><strong>Primera meseta:</strong> condensación (gas y líquido).<br><strong>Segunda meseta:</strong> solidificación (líquido y sólido).</p>')}</div>`);

S('cambios','Taller visual · 1 / 5','Una gráfica cuenta una historia',chalk(trainingCurve(),`<h3>1. Lee los ejes</h3><p>Horizontal → <strong>tiempo</strong>.<br>Vertical → <strong>temperatura</strong>.</p><h3>2. Busca las mesetas</h3><p>Son las líneas horizontales:<br><strong>cambia el estado, no la temperatura.</strong></p><h3>3. Sigue el recorrido</h3><p>🧊 sólido → 💧 líquido → ◌ gas</p><p class="chalk-tip">Sustancia desconocida, pura y a presión constante.</p>`));
S('cambios','Taller visual · 2 / 5','Lee las cinco etapas',chalk(trainingCurve(),`<div class="chalk-stage"><b>A</b><p>🧊 <strong>Sólido</strong>: se calienta hasta 40 °C.</p></div><div class="chalk-stage"><b>B</b><p>🧊 + 💧 <strong>Fusión</strong> a 40 °C.</p></div><div class="chalk-stage"><b>C</b><p>💧 <strong>Líquido</strong>: de 40 a 100 °C.</p></div><div class="chalk-stage"><b>D</b><p>💧 + ◌ <strong>Ebullición</strong> a 100 °C.</p></div><div class="chalk-stage"><b>E</b><p>◌ <strong>Gas</strong>: sigue calentándose.</p></div>`)+reveal('newCurve','Comprueba: ¿qué hay a 70 °C y a los 4 min?','<p><strong>A 70 °C:</strong> líquido.</p><p><strong>A los 4 minutos:</strong> sólido y líquido, durante la fusión.</p><p><strong>No es agua:</strong> su punto de fusión es 40 °C.</p>'));
S('cambios','Taller visual · 3 / 5','Compara dos curvas de enfriamiento',chalk(curvePlot([{points:[[0,50],[3,20],[7,20],[12,-10]],color:'#ffc472'},{points:[[0,50],[5,-10],[9,-10],[12,-30]],color:'#a59cff'}],{min:-40,max:60,tmax:12,ticks:[-30,-10,20,50],xticks:[0,3,6,9,12]}),`<h3><span style="color:#ffc472">● Sustancia A</span><br><span style="color:#a59cff">● Sustancia B</span></h3><div class="chalk-reveals explicit-curve-questions" id="curveQuestions">${[['mesetaTemp','¿A qué temperatura aparece cada meseta?','<p><strong>A: 20 °C.</strong><br><strong>B: −10 °C.</strong></p>'],['mesetaProcess','¿Qué ocurre en esas mesetas?','<p>El líquido <strong>se solidifica</strong>. Coexisten sólido y líquido; la temperatura permanece constante.</p>'],['mesetaIdentity','¿Son la misma sustancia?','<p><strong>No.</strong> A la misma presión, sus puntos de solidificación son distintos.</p>'],['compareCurve','¿En qué estado están a 5 °C?','<p><strong>A:</strong> 5 &lt; 20 → sólido.<br><strong>B:</strong> 5 &gt; −10 → líquido, por debajo de su punto de ebullición.</p>']].map(([id,q,a])=>`<section class="curve-question"><p class="curve-question-label">${q}</p>${reveal(id,'Mostrar respuesta',a)}</section>`).join('')}</div>`));
S('cambios','Taller visual · 4 / 5','De una tabla a una gráfica',`<div class="chalk-lesson"><div class="chalk-chart"><div id="tablePlot">${curvePlot([],{min:0,max:80,tmax:12,ticks:[0,20,50,80],xticks:[0,2,4,6,8,10,12]})}</div></div><div class="chalk-notes"><h3>Una sustancia Z se calienta</h3><table class="teaching-table"><tr><th>t (min)</th>${[0,2,4,6,8,10,12].map(t=>`<td>${t}</td>`).join('')}</tr><tr><th>T (°C)</th>${[10,30,50,50,50,60,70].map(t=>`<td>${t}</td>`).join('')}</tr></table><p><b>①</b> Elige escalas regulares.</p><p><b>②</b> Marca cada pareja (tiempo, temperatura).</p><p><b>③</b> Une los puntos en orden.</p><button class="btn" id="plotStep">Marcar los puntos</button><p id="plotTip" class="chalk-tip">Empieza en (0 min, 10 °C), no en el origen.</p></div></div>`);
S('cambios','Taller visual · 5 / 5','Compara la temperatura y decide el estado',`<div class="state-comparison-lesson"><div class="state-data"><strong>Sustancia desconocida</strong> · Fusión: <b>−15 °C</b> · Ebullición: <b>65 °C</b><p>A la misma presión, compara la temperatura con esos dos límites.</p></div><div class="three state-example-cards"><section><h3>−30 °C</h3><p>−30 &lt; −15</p><p>Está por debajo de la fusión.</p>${reveal('stateSolid','¿Qué estado?','<p>🧊 <strong>Sólido</strong></p>')}</section><section><h3>25 °C</h3><p>−15 &lt; 25 &lt; 65</p><p>Está entre fusión y ebullición.</p>${reveal('stateLiquid','¿Qué estado?','<p>💧 <strong>Líquido</strong></p>')}</section><section><h3>90 °C</h3><p>90 &gt; 65</p><p>Está por encima de la ebullición.</p>${reveal('stateGas','¿Qué estado?','<p>◌ <strong>Gas</strong></p>')}</section></div><p class="state-boundary">En <strong>−15 °C</strong> pueden coexistir sólido y líquido; en <strong>65 °C</strong>, líquido y gas. Para describir el cambio, necesitamos saber si se calienta o se enfría.</p></div>`);
S('cambios','Actividad de cuaderno · 1 / 4','Calentamiento: verdadero o falso',`<div class="worksheet-layout"><figure>${worksheetHeatingGraph()}</figure><div><p class="large">Indica cuáles son correctas. <strong>Justifica las falsas.</strong></p><ol type="a" class="worksheet-items"><li>La temperatura de evaporación de la sustancia es 80 °C.</li><li>La temperatura de ebullición de la sustancia es 80 °C.</li><li>El punto de fusión es 0 °C.</li><li>A 25 °C, la sustancia es líquida.</li><li>Mientras el sólido funde, la temperatura pasa de 0 °C a 14 °C.</li><li>Es el calentamiento de un cubito de hielo.</li></ol><a class="btn alt" href="assets/ejercicios-graficas.pdf" target="_blank" rel="noopener">Abrir la ficha completa ↗</a></div></div>`);
S('cambios','Actividad de cuaderno · 2 / 4','Compara los líquidos A y B',`<div class="worksheet-layout"><figure><img src="assets/ficha-grafica-2.webp" alt="Gráficas originales de enfriamiento de A y B: mesetas a 0 y menos 39 grados Celsius"></figure><div><p>Dos líquidos, de la misma masa, se enfrían desde 10 °C.</p><ol type="a" class="worksheet-items"><li>¿Son la misma sustancia?</li><li>¿Qué propiedad o magnitud específica se interpreta en la gráfica?</li><li>¿Cuál de los dos líquidos puede ser agua?</li><li>¿En qué estado están a los 10 minutos?</li><li>¿En qué estado están a −8 °C?</li></ol><p class="note">Justifica cada respuesta con la meseta o la posición del punto.</p></div></div>`);
S('cambios','Actividad de cuaderno · 3 / 4','Dibuja la curva de la naftalina',`<div class="panel blue"><p>Un tubo con naftalina se calienta lentamente al baño María. Se mide la temperatura cada cuatro minutos.</p><table class="teaching-table worksheet-table"><tr><th>t (min)</th>${[0,4,8,12,16,20,24,28,32].map(t=>`<td>${t}</td>`).join('')}</tr><tr><th>T (°C)</th>${[20,35,50,65,80,80,80,90,100].map(t=>`<td>${t}</td>`).join('')}</tr></table></div><ol type="a" class="worksheet-items"><li>Elabora la gráfica: temperatura en ordenadas y tiempo en abscisas.</li><li>¿Cuál es su punto de fusión? ¿Y su punto de solidificación?</li><li>¿Cuántos tramos distintos hay? ¿Qué sucede en cada uno?</li><li>¿En qué estado está a 90 °C? Justifica la respuesta.</li></ol>`);
S('cambios','Actividad de cuaderno · 4 / 4','¿En qué estado están a 20 °C?',`<div class="panel blue"><table class="teaching-table worksheet-table"><tr><th>Sustancia</th><th>T de fusión</th><th>T de ebullición</th></tr><tr><td>Yodo</td><td><strong>+113,7 °C</strong></td><td>183 °C</td></tr><tr><td>Cloro</td><td>−101 °C</td><td>−35 °C</td></tr><tr><td>Alcohol</td><td>−114 °C</td><td>78,4 °C</td></tr></table><p class="large">Determina el estado de cada sustancia a <strong>20 °C</strong> y justifica la respuesta comparando temperaturas.</p></div>`);


const graphCorrections=[
 {title:'1 · Calentamiento: verdadero o falso',html:`<div class="correction-layout"><div>${worksheetHeatingGraph()}<p class="correction-tip">Fusión: 14 °C · Ebullición: 80 °C</p></div><div class="correction-list"><p><b>a) Falsa.</b> La evaporación no ocurre a una única temperatura.</p><p><b>b) Verdadera.</b> La meseta superior marca la ebullición a 80 °C.</p><p><b>c) Falsa.</b> Funde a 14 °C; 0 °C es la temperatura inicial.</p><p><b>d) Verdadera.</b> 14 &lt; 25 &lt; 80 → líquido.</p><p><b>e) Falsa.</b> Durante la fusión se mantiene a 14 °C.</p><p><b>f) Falsa.</b> El agua funde a 0 °C y hierve a 100 °C a presión atmosférica.</p></div></div>`},
 {title:'2 · Comparamos A y B',html:`<div class="correction-layout"><figure><img src="assets/ficha-grafica-2.webp" alt="Gráfico original de las curvas de enfriamiento A y B"></figure><div class="correction-list"><p><b>a) No.</b> Sus mesetas están a distintas temperaturas: A a 0 °C; B a −39 °C (a la misma presión).</p><p><b>b)</b> El <strong>punto de solidificación</strong>, que coincide con el de fusión.</p><p><b>c) A puede ser agua.</b> Solidifica a 0 °C. La gráfica, por sí sola, no demuestra su identidad.</p><p><b>d) A los 10 min:</b> A está sólido; B contiene <strong>líquido y sólido</strong>, durante la solidificación.</p><p><b>e) A −8 °C:</b> A está sólido (−8 &lt; 0); B está líquido (−8 &gt; −39).</p></div></div>`},
 {title:'3 · Curva de la naftalina',html:`<div class="correction-layout"><div class="correction-chart">${curvePlot([{points:[[0,20],[4,35],[8,50],[12,65],[16,80],[20,80],[24,80],[28,90],[32,100]],color:'#cf7354'}],{min:0,max:110,tmax:32,ticks:[0,20,50,80,100],xticks:[0,8,16,24,32]})}</div><div class="correction-list"><p><b>a)</b> Tiempo en el eje horizontal; temperatura en el vertical. Se representan todos los puntos de la tabla.</p><p><b>b)</b> Fusión y solidificación: <strong>80 °C</strong>.</p><p><b>c) Tres tramos:</b><br>0–16 min: se calienta el sólido.<br>16–24 min: fusión a 80 °C, sólido + líquido.<br>24–32 min: se calienta el líquido.</p><p><b>d) A 90 °C:</b> líquido. La fusión ha terminado y todavía no aparece una meseta de ebullición.</p><p class="correction-tip">La fusión dura 24 − 16 = <strong>8 min</strong>.</p></div></div>`},
 {title:'4 · Estados a 20 °C',html:`<table class="teaching-table worksheet-table"><tr><th>Sustancia</th><th>Comparamos</th><th>Estado</th></tr><tr><td>Yodo</td><td>20 &lt; 113,7 °C</td><td>🧊 <strong>Sólido</strong></td></tr><tr><td>Cloro</td><td>20 &gt; −35 °C</td><td>◌ <strong>Gas</strong></td></tr><tr><td>Alcohol</td><td>−114 &lt; 20 &lt; 78,4 °C</td><td>💧 <strong>Líquido</strong></td></tr></table><p class="correction-tip">Por debajo de fusión → sólido. Entre fusión y ebullición → líquido. Por encima de ebullición → gas.</p>`}
];
S('cambios','Taller de corrección · 4 actividades','Comprueba y entiende tus respuestas',`<div class="correction-workshop"><nav class="correction-tabs" aria-label="Elegir actividad corregida">${graphCorrections.map((g,i)=>`<button class="btn alt" data-correction="${i}" aria-pressed="false">Actividad ${i+1}</button>`).join('')}</nav><div id="correctionBody"></div><div class="correction-nav"><button class="btn alt" id="correctionPrev">← Anterior</button><span id="correctionCounter"></span><button class="btn" id="correctionNext">Siguiente →</button></div></div>`);

S('leyes','4 · Leyes de los gases','Leyes de los gases',`<figure class="notebook-sketchnote phase-poster gas-laws-cover"><img src="assets/leyes-gases-portada.webp" width="1672" height="941" alt="Diagrama de árbol de las leyes de los gases: Boyle-Mariotte, temperatura constante, P₁V₁=P₂V₂; Charles, presión constante, V₁/T₁=V₂/T₂; Gay-Lussac, volumen constante, P₁/T₁=P₂/T₂. Temperatura en kelvin: T=t+273."></figure>`);
S('leyes','Método de resolución','Cinco pasos para un problema',`<div class="problem-method">${['Subraya lo que permanece constante.','Anota datos iniciales y finales.','Pasa la temperatura a K y unifica unidades.','Escribe la ley y despeja la incógnita.','Comprueba las unidades y si el resultado tiene sentido.'].map((t,i)=>`<div class="step"><b>${i+1}</b><p>${t}</p></div>`).join('')}</div>`);
S('leyes','Lámina explicativa','Ley de Boyle-Mariotte',`<figure class="notebook-sketchnote phase-poster gas-law-sheet"><img src="assets/lamina-boyle-mariotte.webp" width="1491" height="1055" alt="Temperatura constante. P₁V₁=P₂V₂. Ejemplo: 120 cm³ a 1 atm pasan a 60 cm³ y 2 atm."></figure>`);
S('leyes','Lámina explicativa','Ley de Charles',`<figure class="notebook-sketchnote phase-poster gas-law-sheet"><img src="assets/lamina-charles.webp" width="1491" height="1055" alt="Presión constante. V₁/T₁=V₂/T₂. Ejemplo: 2 L a 300 K pasan a 2,2 L a 330 K."></figure>`);
S('leyes','Lámina explicativa','Ley de Gay-Lussac',`<figure class="notebook-sketchnote phase-poster gas-law-sheet"><img src="assets/lamina-gay-lussac.webp" width="1491" height="1055" alt="Volumen constante. P₁/T₁=P₂/T₂. Ejemplo: 1,5 atm a 300 K pasan a 2 atm a 400 K."></figure>`);
S('leyes','Ahora tú','Actividades del libro',book(36,'ejercicios 17, 19, 20 y 24','Antes de calcular, escribe qué magnitud no varía en cada ejercicio.'));
S('atmosfera','5 · La atmósfera terrestre','Una capa de gases',`<div class="two">${panel('<p class="hero-text">La atmósfera es la capa de gases que rodea la Tierra.</p><p>Su aire ejerce presión sobre las superficies.</p>','blue')}<div class="panel center"><div style="font-size:clamp(5rem,12vw,10rem)">🌍</div></div></div>${question('Para introducir','Si el aire no se ve, ¿cómo podríamos demostrar que ejerce presión?')}`);
S('atmosfera','Composición del aire','¿De qué está hecho?',`<div class="two">${notebook('<p class="large">El aire está formado principalmente por <strong>nitrógeno (aprox. 78 %)</strong> y <strong>oxígeno (aprox. 21 %)</strong>. El resto corresponde a otros gases.</p>')}<div class="panel"><svg viewBox="0 0 340 280" role="img" aria-label="Composición aproximada del aire: 78 % nitrógeno, 21 % oxígeno, 1 % otros gases"><circle cx="170" cy="140" r="100" fill="none" stroke="#c5e8f6" stroke-width="62"/><circle cx="170" cy="140" r="100" fill="none" stroke="#2685b4" stroke-width="62" stroke-dasharray="490 628" transform="rotate(-90 170 140)"/><circle cx="170" cy="140" r="100" fill="none" stroke="#e69a50" stroke-width="62" stroke-dasharray="132 628" stroke-dashoffset="-490" transform="rotate(-90 170 140)"/><text x="170" y="145" text-anchor="middle" fill="#23475c" font-size="27" font-weight="bold">AIRE</text></svg><p class="small center">78 % N₂ · 21 % O₂ · ~1 % otros gases</p></div></div>`);
S('atmosfera','Torricelli','¿Cómo se midió la presión?',`<div class="two"><div class="diagram">${torricelli}</div>${panel('<h3>La observación</h3><p>Torricelli llenó un tubo de mercurio y lo invirtió sobre un recipiente que también lo contenía. La columna se sostuvo a una altura aproximada de <strong>760 mm</strong> al nivel del mar.</p><p>La presión de la atmósfera sobre el mercurio del recipiente equilibra la de la columna.</p>','blue')}</div>${question('Señala en el dibujo','¿Dónde empuja la atmósfera y dónde queda el espacio sin aire sobre la columna?')}`);
S('atmosfera','Cuaderno · Presión atmosférica','El experimento de Torricelli',`${notebook('<p class="large">La <strong>presión atmosférica</strong> es la fuerza por unidad de superficie que ejerce el aire de la atmósfera.</p><p>El experimento de Torricelli mostró esa presión al sostener una columna de mercurio de unos 760 mm al nivel del mar.</p><span class="formula">1 atm = 760 mmHg</span>')}${question('Explica en voz alta','¿Qué ocurre con la columna si no hay suficiente presión exterior para sostenerla?')}`);
S('atmosfera','Subimos una montaña','La presión cambia con la altura',`<div class="two">${panel('<p class="hero-text">A medida que aumenta la altura, queda menos aire encima de nosotros.</p><p class="large"><strong>La presión atmosférica disminuye.</strong></p>','blue')}<div class="panel center"><div style="font-size:clamp(5rem,12vw,10rem)">🏔️</div></div></div>${question('Piensa','¿Será mayor la presión al nivel del mar o en la cima de una montaña?')}`);
S('atmosfera','Isobaras','Líneas de igual presión',`${notebook('<p class="large">Las <strong>isobaras</strong> son líneas que unen lugares que tienen la misma presión atmosférica.</p><p><strong>A:</strong> alta presión o anticiclón. <strong>B:</strong> baja presión o borrasca.</p>')}<div class="big-space"></div>${question('Lectura','Si el número de una isobara aumenta al acercarnos al centro, ¿es una zona de alta o baja presión?')}`);
