S('atmosfera','Ahora tú','Actividades del libro',book(38,'ejercicios 31 y 32','Repasa el experimento de Torricelli, la altura y la interpretación de las isobaras.'));
S('laboratorio','Laboratorio · Presión','El vaso y la tarjeta',`<div class="two">${panel('<h3>Demostración</h3><p>Llena un vaso con agua, cubre su boca con una tarjeta e inviértelo con cuidado sobre una bandeja.</p><p class="note">Primero hacemos una predicción. La profesora realiza la demostración siguiendo las normas del laboratorio.</p>','blue')}${panel('<h3>Antes de verlo</h3><p class="hero-text">¿Qué crees que ocurrirá si se retira la mano de la tarjeta?</p><div class="space"></div>','green')}${reveal('glassans','Mostrar explicación','<p>Si la tarjeta queda sujeta, la presión atmosférica ejerce una fuerza hacia arriba sobre ella. El resultado depende también de la colocación y del sellado del vaso.</p>')}</div>`);
S('laboratorio','Laboratorio · Cambios de estado','Una meseta de temperatura',`<div class="two">${panel('<h3>Observación</h3><p>Registramos la temperatura a intervalos durante un cambio de estado. Representamos los datos en una gráfica.</p><p class="large">¿Qué ocurre durante el tramo horizontal?</p>','blue')}<div class="diagram">${graph()}</div></div>${reveal('plateauans','Mostrar respuesta','<p>La temperatura permanece constante mientras se produce el cambio de estado.</p>')}`);
S('ficha','Ficha 1 · Leyes de gases','Primero intenta. Después corrige.',`<div class="two">${panel('<h3>En clase</h3><p class="large">Cada ejercicio ocupa una pantalla para proyectarlo y resolverlo en el cuaderno.</p><p>La pantalla siguiente muestra los datos, la ley, el despeje y el resultado.</p>','blue')}${panel('<h3>Recuerda</h3><p>Temperaturas en kelvin y magnitudes de cada pareja en la misma unidad.</p><p>En esta ficha usamos <strong>T(K) = t(°C) + 273</strong>, como en sus soluciones.</p>','yellow')}</div><div class="big-space"></div>`);
gasData.forEach((g,i)=>{S('ficha',`Ficha 1 · Ejercicio ${i+1}`,'Resuelve en el cuaderno',`${panel(`<h3>Ejercicio ${i+1}</h3><p class="large">${g[0]}</p>`,'blue')}<div class="space"></div><p class="small">No avances a la corrección hasta haber elegido la ley y despejado.</p>`);S('ficha',`Ficha 1 · Corrección ${i+1}`,'Comprueba tu procedimiento',`<div class="panel blue"><span class="tag">Ejercicio ${i+1}</span><div class="step"><b>1</b><p>${g[1]}</p></div><div class="step"><b>2</b><p>${g[2]}</p></div></div>${question('Revisa','¿La respuesta tiene las unidades pedidas? ¿Es razonable al comparar los datos iniciales y finales?')}`)});
S('voluntarios','Práctica voluntaria','Tres más para entrenar',`<div class="panel green"><p class="hero-text">Son problemas nuevos del mismo tipo que los de la ficha.</p><p>Resuelve cada uno antes de abrir su corrección.</p></div><div class="big-space"></div>`);
extras.forEach((g,i)=>S('voluntarios',`Práctica voluntaria · ${i+1}`,`Problema ${i+1}`,`${panel(`<p class="large">${g[0]}</p>`,'green')}<div class="space"></div>${reveal('extra'+i,'Mostrar corrección',`<p class="large">${g[1]}</p>`)}`));
S('voluntarios','Repaso final','¿Qué debes saber hacer?',`<div class="two"><div>${['Comparar estados y convertir presión y temperatura al SI.','Explicar con partículas la presión, el sólido y el líquido.','Nombrar cambios, deducir estados e interpretar gráficas.','Elegir y aplicar las tres leyes de los gases.','Explicar Torricelli, la altura y leer isobaras.'].map((t,i)=>`<div class="step"><b>${i+1}</b><p>${t}</p></div>`).join('')}</div>${panel('<h3>Tu autoevaluación</h3><p>Marca mentalmente lo que puedes explicar sin ayuda. Si algo falla, vuelve a las pantallas de ese epígrafe y prueba otra vez.</p><div class="space"></div>','blue')}</div>`);
S('cierre','Expediente 01 · Volvemos al misterio','¿Qué piensas ahora?',`<div class="mystery-return"><img src="assets/botella-misterio.webp" alt="La botella deformada del misterio inicial"><div><h3>La botella que nadie apretó</h3><p>Ahora conoces los estados, las partículas, la temperatura y la presión. <strong>¿Cómo explicarías lo ocurrido?</strong></p><p class="return-notebook"><strong>Abre el cuaderno y descubre tu hipótesis inicial.</strong><br>¿Qué pensabas al empezar? ¿Qué cambiarías ahora?</p></div></div><div class="notebook-hypothesis"><strong>✍️ En el cuaderno · Mi explicación final</strong><p>Escribe tu nueva explicación usando presión, temperatura y partículas.</p><span>Compárala con la inicial: ¿qué mantienes y qué corriges?</span></div>${reveal('mystery-resolution','Descubrir qué ocurrió en este caso','<p>En este caso, la botella de plástico se cerró con aire caliente en su interior y después se enfrió. Al enfriarse el gas, disminuyó su presión. Cuando la presión exterior fue suficientemente mayor que la interior, deformó la botella hacia dentro.</p><p><strong>El aire de fuera ejerce presión aunque no lo veamos.</strong> Compara esta explicación con tu hipótesis.</p>')}`);
let liquidAnim=0;
let current=0;const stage=document.getElementById('stage');const indexes=Object.fromEntries(chapters.map(c=>[c.id,slides.findIndex(s=>s.chapter===c.id)]));indexes.indice=slides.findIndex(s=>s.chapter==='indice');
function go(n){current=Math.max(0,Math.min(slides.length-1,n));render();window.scrollTo(0,0);location.hash=slides[current].chapter==='indice'?'indice':current===0?'inicio':'p'+(current+1)}
function render(){const s=slides[current];const app=document.getElementById('app');app.classList.toggle('opening',current===0);document.querySelector('.mast').hidden=current!==0;document.querySelector('.credit img').hidden=current!==0;const chapter=chapters.find(c=>c.id===s.chapter);const start=chapter&&indexes[s.chapter]===current;const poster=s.html.includes('class="tcm-infographic"')||s.html.includes('phase-poster');stage.innerHTML=`<article class="slide ${s.chapter==='indice'?'index':''} ${current===5||poster?'sketchnote-slide':''} ${start?'chapter-start':''}">${s.chapter==='indice'||current===5||poster?s.html:`<div class="slide-title"><div class="kicker">${start?chapter.name:s.kicker}</div><h2>${s.title}</h2></div>${s.html}`}</article>`;document.getElementById('counter').textContent=String(current+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0');document.getElementById('prev').disabled=current===0;document.getElementById('next').disabled=current===slides.length-1;wireInteractions();fitSlide()}
function fitSlide(){
 const slide=stage.querySelector('.slide');if(!slide)return;if(slide.classList.contains('sketchnote-slide')){
  const img=slide.querySelector('img');const height=Math.max(1,stage.clientHeight-6);const width=Math.max(1,stage.clientWidth-6);const ratio=slide.querySelector('.gas-law-sheet')?Number(img.getAttribute('width'))/Number(img.getAttribute('height')):slide.querySelector('.tcm-infographic')?1491/1055:16/9;
  const imageWidth=Math.min(width,height*ratio);slide.style.width='100%';slide.style.height=height+'px';slide.style.transform='none';
  if(img){img.style.width=imageWidth+'px';img.style.height=(imageWidth/ratio)+'px'}return
 }
 slide.style.transform='none';slide.style.width='100%';slide.classList.remove('fit-tight');
 const available=Math.max(1,stage.clientHeight-3);
 if(slide.scrollHeight>available)slide.classList.add('fit-tight');
 // Test each size with its real text wrapping; never leave a zoom that overflows.
 const max=stage.clientWidth>=1000?1.16:1;
 let chosen=.1;
 for(let scale=max;scale>=.1;scale-=.01){
  slide.style.width=(100/scale)+'%';
  if(slide.scrollHeight*scale<=available){chosen=scale;break}
 }
 slide.style.width=(100/chosen)+'%';
 slide.style.transform=`scale(${chosen})`;
 slide.style.transformOrigin='top left';
}

const propertyGameState={index:0,answers:{},checked:{},solved:{}};
function wirePropertyGames(){
 const body=document.getElementById('propertyGameBody');if(!body)return;
 const prev=document.getElementById('propertyGamePrev'),next=document.getElementById('propertyGameNext');
 const normalize=v=>v.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ');
 function bindSyringe(){const cr=document.getElementById('compressRange');if(!cr)return;cr.oninput=()=>{const dx=Number(cr.value)*1.9;document.getElementById('compressPlunger').setAttribute('transform',`translate(${dx} 0)`);document.getElementById('compressedAir').setAttribute('x',110+dx);document.getElementById('compressedAir').setAttribute('width',274-dx);document.getElementById('compressText').textContent=dx?'El aire ocupa menos volumen':'Volumen inicial del aire'};}
 function draw(){
 const i=propertyGameState.index,g=propertyGameData[i],score=Object.values(propertyGameState.solved).filter(Boolean).length;
 document.getElementById('propertyGameCounter').textContent=i<6?`Juego ${i+1} de 6`:'Resultado';document.getElementById('propertyGameScore').textContent=`Retos resueltos: ${score} / 6`;
 prev.disabled=i===0;next.hidden=i===6;next.disabled=i<6&&!propertyGameState.checked[i];next.textContent=i===5?'Ver resultado →':'Siguiente juego →';
 if(i===6){body.innerHTML=`<div class="game-result"><h3>Has terminado los seis juegos</h3><p class="hero-text">${score} de 6 retos resueltos</p><p>${score===6?'¡Muy bien! Has aplicado forma, volumen y compresibilidad.':'Vuelve a los retos pendientes y usa sus explicaciones para repasarlos.'}</p><div class="game-result-list">${propertyGameData.map((q,n)=>`<button class="btn alt" data-review-game="${n}">${propertyGameState.solved[n]?'✓':'↻'} ${q.title}</button>`).join('')}</div><button class="btn" id="propertyGameReset">Volver a jugar desde el principio</button></div>`;body.querySelectorAll('[data-review-game]').forEach(b=>b.onclick=()=>{propertyGameState.index=Number(b.dataset.reviewGame);draw()});document.getElementById('propertyGameReset').onclick=()=>{propertyGameState.index=0;propertyGameState.answers={};propertyGameState.checked={};propertyGameState.solved={};draw()};fitSlide();return;}
 let inputs='';
 if(g.type==='choice'||g.type==='syringe')inputs=`<div class="game-options">${g.options.map((o,n)=>`<button class="game-option ${propertyGameState.answers[i]===n?'selected':''}" data-game-option="${n}">${o}</button>`).join('')}</div>`;
 if(g.type==='volume')inputs='<div class="game-fill"><label>El agua sigue ocupando <input id="gameVolume" type="text" inputmode="decimal" autocomplete="off" aria-label="Volumen final del agua"> mL.</label><label>Lo que cambia es su <input id="gameShape" type="text" autocomplete="off" aria-label="Característica que cambia al trasvasar el agua">.</label></div>';
 if(g.type==='examples')inputs='<div class="game-fill"><label>Sólido: <input id="gameSolid" autocomplete="off"></label><label>Líquido: <input id="gameLiquid" autocomplete="off"></label><label>Gaseoso: <input id="gameGas" autocomplete="off"></label></div>';
 const art=g.type==='syringe'?`<div class="game-syringe">${syringeGameSvg}<label>Empuja el émbolo <input id="compressRange" type="range" min="0" max="100" value="0"></label><p id="compressText">Volumen inicial del aire</p></div>`:g.art?`<div class="property-art art-${g.art}" role="img" aria-label="Ejemplo visual para el reto"></div>`:'<div class="game-example-art" aria-hidden="true">🧊<br>💧<br>🎈</div>';
 body.innerHTML=`<h3 class="game-title">${g.title}</h3><div class="game-layout"><div class="game-visual">${art}</div><div><p class="game-prompt">${g.prompt}</p>${inputs}<button class="btn" id="propertyGameCheck">Comprobar</button><p id="propertyGameFeedback" class="game-feedback" role="status"></p></div></div>`;
 if(g.type==='volume'||g.type==='examples'){const values=propertyGameState.answers[i]||[];body.querySelectorAll('.game-fill input').forEach((e,n)=>{e.value=values[n]||'';e.addEventListener('input',()=>{propertyGameState.answers[i]=Array.from(body.querySelectorAll('.game-fill input'),el=>el.value);document.getElementById('propertyGameFeedback').textContent=''})})}
 body.querySelectorAll('[data-game-option]').forEach(b=>b.onclick=()=>{propertyGameState.answers[i]=Number(b.dataset.gameOption);body.querySelectorAll('.game-option').forEach(el=>el.classList.toggle('selected',el===b));document.getElementById('propertyGameFeedback').textContent=''});
 document.getElementById('propertyGameCheck').onclick=()=>{
  const f=document.getElementById('propertyGameFeedback');let ok=false;
  if(g.type==='choice'||g.type==='syringe'){if(propertyGameState.answers[i]===undefined){f.textContent='Elige una respuesta antes de comprobar.';fitSlide();return}ok=propertyGameState.answers[i]===g.correct}
  else {const a=Array.from(body.querySelectorAll('.game-fill input'),el=>normalize(el.value));if(a.some(v=>!v)){f.textContent='Completa todos los huecos antes de comprobar.';fitSlide();return}propertyGameState.answers[i]=Array.from(body.querySelectorAll('.game-fill input'),el=>el.value);if(g.type==='volume')ok=Number(a[0].replace(',','.'))===200&&a[1]==='forma';else ok=a[0]==='hielo'&&['agua','agua liquida'].includes(a[1])&&a[2]==='aire'}
  propertyGameState.checked[i]=true;propertyGameState.solved[i]=ok;f.textContent=(ok?'✓ Correcto. ':'↻ Revisa tu respuesta. ')+g.explanation;f.className='game-feedback '+(ok?'ok':'review');next.disabled=false;document.getElementById('propertyGameScore').textContent=`Retos resueltos: ${Object.values(propertyGameState.solved).filter(Boolean).length} / 6`;fitSlide();
 };
 bindSyringe();fitSlide();
 }
 prev.onclick=()=>{if(propertyGameState.index>0){propertyGameState.index--;draw()}};next.onclick=()=>{if(propertyGameState.index<6&&propertyGameState.checked[propertyGameState.index]){propertyGameState.index++;draw()}};draw();
}

function wireConversions(){
 const format=n=>Number(n.toPrecision(10)).toLocaleString('es-ES',{maximumFractionDigits:8}).replace(/\./g,' ');
 const parseAnswer=s=>Number(s.trim().replace(/\s/g,'').replace(',','.'));
 const tv=document.getElementById('temperatureValue');
 if(tv){let expected;document.getElementById('temperatureShow').onclick=()=>{const value=Number(tv.value),offset=273,toK=document.getElementById('temperatureDirection').value==='toK';if(!tv.value||!Number.isFinite(value)){document.getElementById('temperatureSteps').textContent='Escribe una temperatura.';return}if((toK&&value < -offset)||(!toK&&value<0)){document.getElementById('temperatureSteps').textContent='Esa temperatura queda por debajo del cero absoluto. Revisa el dato.';document.getElementById('temperaturePractice').hidden=true;return}expected=toK?value+offset:value-offset;document.getElementById('temperatureSteps').innerHTML=`<p><strong>${toK?'De °C a K: suma':'De K a °C: resta'} ${format(offset)}.</strong></p><p class="conversion-equation">${format(value)} ${toK?'+':'−'} ${format(offset)} = ? ${toK?'K':'°C'}</p>`;document.getElementById('temperaturePractice').hidden=false;document.getElementById('temperatureAnswer').value='';document.getElementById('temperatureFeedback').textContent='';fitSlide()};document.getElementById('temperatureCheck').onclick=()=>{const entered=document.getElementById('temperatureAnswer').value,ok=entered.trim()!==''&&Math.abs(parseAnswer(entered)-expected)<.011;const f=document.getElementById('temperatureFeedback');f.textContent=ok?'Correcto: '+format(expected)+(document.getElementById('temperatureDirection').value==='toK'?' K':' °C'):'Revisa la suma o la resta.';f.className='feedback'+(ok?' ok':'');fitSlide()};[tv,document.getElementById('temperatureDirection')].forEach(e=>e.addEventListener('input',()=>{document.getElementById('temperaturePractice').hidden=true;document.getElementById('temperatureSteps').textContent='Pulsa el botón para actualizar el procedimiento.';fitSlide()}))}
 const pv=document.getElementById('pressureValue');if(pv){const pa={atm:101325,Pa:1,mmHg:101325/760,bar:100000};let expected,target;document.getElementById('pressureShow').onclick=()=>{const value=Number(pv.value),from=document.getElementById('pressureFrom').value,to=document.getElementById('pressureTo').value;if(!pv.value||!Number.isFinite(value)||value<0){document.getElementById('pressureSteps').textContent='Escribe una presión no negativa.';document.getElementById('pressurePractice').hidden=true;return}target=to;expected=value*pa[from]/pa[to];if(from===to){document.getElementById('pressureSteps').innerHTML='<p>La unidad ya es la que quieres obtener: no hay que convertir.</p>'}else{let num,den;
 if(from==='atm'||to==='atm'){const eq={Pa:101325,mmHg:760,bar:1.01325};if(from==='atm'){num=eq[to];den=1}else{num=1;den=eq[from]}}
 else if(from==='bar'&&to==='Pa'){num=100000;den=1}else if(from==='Pa'&&to==='bar'){num=1;den=100000}else if(from==='mmHg'&&to==='Pa'){num=101325;den=760}else if(from==='Pa'&&to==='mmHg'){num=760;den=101325}else if(from==='bar'&&to==='mmHg'){num=760;den=1.01325}else if(from==='mmHg'&&to==='bar'){num=1.01325;den=760}else{num=pa[from];den=pa[to]}
 document.getElementById('pressureSteps').innerHTML=`<p>La equivalencia es: <strong>${format(den)} ${from} = ${format(num)} ${to}</strong>.</p><div class="factor-expression"><span>${format(value)} <s>${from}</s></span><span>×</span><span class="fraction"><span>${format(num)} ${to}</span><span>${format(den)} <s>${from}</s></span></span><span>= ? ${to}</span></div><p class="small">La unidad ${from} se cancela. Queda ${to}.</p>`}
 document.getElementById('pressurePractice').hidden=false;document.getElementById('pressureAnswer').value='';document.getElementById('pressureFeedback').textContent='';fitSlide()};document.getElementById('pressureCheck').onclick=()=>{const val=document.getElementById('pressureAnswer').value,ok=val.trim()!==''&&Math.abs(parseAnswer(val)-expected)<=Math.max(.000000001,Math.abs(expected)*.0001);const f=document.getElementById('pressureFeedback');f.textContent=ok?'Correcto: '+format(expected)+' '+target:'Revisa la operación y la posición de las unidades.';f.className='feedback'+(ok?' ok':'');fitSlide()};[pv,document.getElementById('pressureFrom'),document.getElementById('pressureTo')].forEach(e=>e.addEventListener('input',()=>{document.getElementById('pressurePractice').hidden=true;document.getElementById('pressureSteps').textContent='Pulsa el botón para actualizar el factor.';fitSlide()}))}
}

function wireInteractions(){wireCurveQuestions();wireGraphCorrections();wireWaterStates();wireGraphTable();const liquid=document.getElementById("liquidCanvas");if(liquid)startLiquid(liquid);wirePropertyGames();wireConversions();stage.querySelectorAll("[data-situation]").forEach(b=>b.addEventListener("click",()=>{b.textContent=b.dataset.situation;b.classList.add("situation-revealed");fitSlide()}));stage.querySelectorAll("img").forEach(img=>img.addEventListener("load",fitSlide,{once:true}));stage.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click',()=>go(indexes[b.dataset.jump])));stage.querySelectorAll('.reveal').forEach(b=>b.addEventListener('click',()=>{const a=document.getElementById(b.dataset.target),v=a.classList.toggle('visible');b.setAttribute('aria-expanded',v);b.textContent=v?'Ocultar respuesta':'Mostrar respuesta';fitSlide()}));stage.querySelectorAll('.blank').forEach(b=>{const act=()=>{b.textContent=b.dataset.answer;b.classList.add('filled');fitSlide()};b.addEventListener('click',act);b.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act()}})});stage.querySelectorAll('.choice').forEach(b=>b.addEventListener('click',()=>{const group=b.dataset.group;stage.querySelectorAll(`.choice[data-group="${group}"]`).forEach(x=>x.classList.remove('selected'));b.classList.add('selected');const f=document.getElementById('choice-feedback');f.textContent=b.dataset.correct?'¡Correcto!':'Piénsalo otra vez.';f.className='feedback'+(b.dataset.correct?' ok':'');fitSlide()}));const p=document.getElementById('piston');if(p){const update=()=>{const pos={1:'15%',2:'38%',3:'65%'}[p.value],label={1:'Volumen mayor · presión menor',2:'Volumen intermedio · presión intermedia',3:'Volumen menor · presión mayor'}[p.value];document.getElementById('pistonHead').style.top=pos;document.getElementById('pistonText').textContent=label};p.addEventListener('input',update);update()}const can=document.getElementById('particlesCanvas');if(can)startParticles(can)}
let animId=0;function startParticles(canvas){cancelAnimationFrame(animId);let paused=false;const pause=document.getElementById('gasPause');if(pause)pause.onclick=()=>{paused=!paused;pause.textContent=paused?'Reanudar':'Pausar'};const ctx=canvas.getContext('2d'),points=Array.from({length:25},(_,i)=>({x:20+(i*83)%470,y:20+(i*59)%260,vx:(i%2?1:-1)*(1+i%4*.25),vy:(i%3?1:-1)*(1+i%5*.16)}));function frame(){if(!canvas.isConnected)return;ctx.clearRect(0,0,520,310);ctx.fillStyle='#e7f5fb';ctx.fillRect(0,0,520,310);ctx.lineWidth=7;ctx.strokeStyle='#458aaa';ctx.strokeRect(5,5,510,300);let speed=+(document.getElementById('agitation')?.value||2);const l=document.getElementById('agit-label');if(l)l.textContent=['','Agitación baja','Agitación media','Agitación alta'][speed];for(const p of points){if(!paused){p.x+=p.vx*speed;p.y+=p.vy*speed;}if(p.x<15||p.x>505)p.vx*=-1;if(p.y<15||p.y>295)p.vy*=-1;ctx.beginPath();ctx.arc(p.x,p.y,6,0,Math.PI*2);ctx.fillStyle='#df8144';ctx.fill()}animId=requestAnimationFrame(frame)}frame()}
document.getElementById('prev').addEventListener('click',()=>go(current-1));document.getElementById('next').addEventListener('click',()=>go(current+1));document.getElementById('home').addEventListener('click',()=>go(indexes.indice));document.getElementById('fullscreen').addEventListener('click',()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen());window.addEventListener('resize',fitSlide);document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,button'))return;if(e.key==='ArrowRight')go(current+1);if(e.key==='ArrowLeft')go(current-1);if(e.key==='Home')go(indexes.indice)});if(location.hash==='#indice')current=indexes.indice;const match=location.hash.match(/^#p(\d+)$/);if(match)current=Math.min(slides.length-1,Math.max(0,+match[1]-1));render();

function wireGraphTable(){const b=document.getElementById('plotStep');if(!b)return;let n=0;const points=[[0,10],[2,30],[4,50],[6,50],[8,50],[10,60],[12,70]];b.onclick=()=>{n=Math.min(2,n+1);const area=document.getElementById('tablePlot');area.innerHTML=curvePlot([{points,color:'#ffc472'}],{min:0,max:80,tmax:12,ticks:[0,20,50,80],xticks:[0,2,4,6,8,10,12]});if(n===1)area.querySelector('polyline').style.display='none';b.textContent=n===1?'Unir y leer la meseta':'Gráfica completa';b.disabled=n===2;document.getElementById('plotTip').textContent=n===1?'Cada punto es una pareja de la tabla. Ahora únelos.':'De 4 a 8 min: fusión a 50 °C. Dura 4 min; coexisten sólido y líquido.';fitSlide()};}

function startLiquid(canvas){cancelAnimationFrame(liquidAnim);const ctx=canvas.getContext('2d');let paused=false,last=0;const points=Array.from({length:88},(_,i)=>({x:38+(i%11)*44+(i%3)*3,y:112+Math.floor(i/11)*29+Math.sin(i*2)*5,vx:Math.cos(i*2.4)*1.1,vy:Math.sin(i*2.4)*1.1}));const btn=document.getElementById('liquidPause');btn.onclick=()=>{paused=!paused;btn.textContent=paused?'Reanudar':'Pausar'};
function frame(t){if(!canvas.isConnected)return;const dt=Math.min(2,(t-last)/16.67||1);last=t;const speed=Number(document.getElementById('liquidSpeed')?.value||2)*.9;
if(!paused){for(let i=0;i<points.length;i++){const p=points[i];p.vx+=Math.sin(t*.0008+i*3.7)*.012;p.vy+=Math.cos(t*.0007+i*2.1)*.012;const v=Math.hypot(p.vx,p.vy);if(v>1.4){p.vx*=1.4/v;p.vy*=1.4/v}p.x+=p.vx*speed*dt;p.y+=p.vy*speed*dt;if(p.x<26){p.x=26;p.vx=Math.abs(p.vx)}if(p.x>534){p.x=534;p.vx=-Math.abs(p.vx)}if(p.y<110){p.y=110;p.vy=Math.abs(p.vy)}if(p.y>346){p.y=346;p.vy=-Math.abs(p.vy)}}
for(let i=0;i<points.length;i++)for(let j=i+1;j<points.length;j++){let a=points[i],b=points[j],dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(d>0&&d<19){let nx=dx/d,ny=dy/d,push=(19-d)/2;a.x-=nx*push;a.y-=ny*push;b.x+=nx*push;b.y+=ny*push;let relative=(a.vx-b.vx)*nx+(a.vy-b.vy)*ny;if(relative>0){a.vx-=relative*nx;a.vy-=relative*ny;b.vx+=relative*nx;b.vy+=relative*ny}}}}
ctx.clearRect(0,0,560,380);ctx.fillStyle='#e0f4fc';ctx.fillRect(16,99,528,260);ctx.strokeStyle='#477d96';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(16,40);ctx.lineTo(16,359);ctx.lineTo(544,359);ctx.lineTo(544,40);ctx.stroke();ctx.strokeStyle='#76c4df';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(20,99);ctx.lineTo(540,99);ctx.stroke();for(const p of points){ctx.beginPath();ctx.arc(p.x,p.y,9,0,Math.PI*2);ctx.fillStyle='#318bb8';ctx.fill();ctx.strokeStyle='#1b567a';ctx.lineWidth=1.5;ctx.stroke()}ctx.fillStyle='#20485e';ctx.font='bold 21px Arial';ctx.fillText('PRÓXIMAS · DESORDENADAS · MÓVILES',48,28);liquidAnim=requestAnimationFrame(frame)}liquidAnim=requestAnimationFrame(frame)}


function wireWaterStates(){const states=['🧊<br><strong>Sólido</strong>','🧊 + 💧<br><strong>Fusión / solidificación</strong>','💧<br><strong>Líquido</strong>','💧 + ◌<br><strong>Ebullición / condensación</strong>','◌<br><strong>Gas</strong>'];stage.querySelectorAll('[data-water-answer]').forEach(button=>{button.onclick=()=>{const open=button.getAttribute('aria-expanded')==='true';button.innerHTML=open?'?':states[Number(button.dataset.waterAnswer)];button.setAttribute('aria-expanded',String(!open));fitSlide()}});}
function wireGraphCorrections(){const body=document.getElementById('correctionBody');if(!body)return;let active=0;const buttons=stage.querySelectorAll('[data-correction]');const draw=()=>{body.innerHTML='<h3>'+graphCorrections[active].title+'</h3>'+graphCorrections[active].html;document.getElementById('correctionCounter').textContent=(active+1)+' / 4';document.getElementById('correctionPrev').disabled=active===0;document.getElementById('correctionNext').disabled=active===3;buttons.forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.correction)===active)));body.querySelectorAll('img').forEach(img=>img.addEventListener('load',fitSlide,{once:true}));fitSlide()};buttons.forEach(b=>b.onclick=()=>{active=Number(b.dataset.correction);draw()});document.getElementById('correctionPrev').onclick=()=>{active=Math.max(0,active-1);draw()};document.getElementById('correctionNext').onclick=()=>{active=Math.min(3,active+1);draw()};draw();}

function wireCurveQuestions(){const group=stage.querySelector('#curveQuestions');if(!group)return;group.querySelectorAll('.reveal').forEach(button=>button.addEventListener('click',()=>{group.querySelectorAll('.reveal').forEach(other=>{if(other===button)return;document.getElementById(other.dataset.target).classList.remove('visible');other.setAttribute('aria-expanded','false');other.textContent='Mostrar respuesta'})}));}
